module ClipboardHelper
  def button_to_copy_to_clipboard(url, &)
    tag.button class: "btn", data: {
      controller: "copy-to-clipboard", action: "copy-to-clipboard#copy",
      copy_to_clipboard_success_class: "btn--success", copy_to_clipboard_content_value: url
    }, &
  end
end

module TimeHelper
  def local_datetime_tag(datetime, style: :time, **attributes)
    tag.time **attributes, datetime: datetime.iso8601, data: { local_time_target: style }
  end
end

module Users::SidebarHelper
  def sidebar_turbo_frame_tag(src: nil, &)
    turbo_frame_tag :user_sidebar, src: src, target: "_top", data: {
      turbo_permanent: true,
      controller: "rooms-list read-rooms turbo-frame",
      rooms_list_unread_class: "unread",
      action: "presence:present@window->rooms-list#read read-rooms:read->rooms-list#read turbo:frame-load->rooms-list#loaded refresh-room:visible@window->turbo-frame#reload".html_safe # otherwise -> is escaped
    }, &
  end
end

class Boost < ApplicationRecord
  belongs_to :message, touch: true
  belongs_to :booster, class_name: "User", default: -> { Current.user }

  scope :ordered, -> { order(:created_at) }
end

class Membership < ApplicationRecord
  include Connectable

  belongs_to :room
  belongs_to :user

  after_destroy_commit { user.reset_remote_connections }

  enum :involvement, %w[ invisible nothing mentions everything ].index_by(&:itself), prefix: :involved_in

  scope :with_ordered_room, -> { includes(:room).joins(:room).order("LOWER(rooms.name)") }
  scope :with_direct_rooms, -> { includes(:room).joins(:room).merge(Room.directs).order(rooms: { updated_at: :desc }) }
  scope :without_direct_rooms, -> { joins(:room).merge(Room.without_directs) }

  scope :visible, -> { where.not(involvement: :invisible) }
  scope :unread,  -> { where.not(unread_at: nil) }

  def read
    update!(unread_at: nil)
  end

  def unread?
    unread_at.present?
  end
end

module Message::Pagination
  extend ActiveSupport::Concern

  PAGE_SIZE = 40

  # Expose Rails' collection-preloading hook while preserving Array pagination and
  # validators. The renderer passes only cache misses to preload_associations.
  class Page < Array
    def self.load(relation, direction, size)
      new(relation.skip_preloading!.public_send(direction, size), relation)
    end

    def initialize(records, relation)
      super(records)
      @relation = relation
    end

    def loaded?
      true
    end

    def preload_associations(records)
      @relation.preload_associations(records)
    end
  end

  included do
    # Keep presentation data lazy until the collection cache knows which messages missed.
    scope :last_page, -> { last_page_of(PAGE_SIZE) }
    scope :first_page, -> { Page.load(ordered, :first, PAGE_SIZE) }

    scope :before, ->(message) { where("created_at < ?", message.created_at) }
    scope :after, ->(message) { where("created_at > ?", message.created_at) }

    scope :page_before, ->(message) { before(message).last_page }
    scope :page_after, ->(message) { after(message).first_page }

    scope :page_created_since, ->(time) { where("created_at > ?", time).first_page }
    # Sorting on +created_at, which no index covers, has SQLite find the few messages updated since
    # through (room_id, updated_at) and sort just those, instead of walking the whole room by
    # (room_id, created_at) looking for them.
    scope :page_updated_since, ->(time) { Page.load(where("updated_at > ?", time).reorder(Arel.sql("+messages.created_at")), :last, PAGE_SIZE) }
  end

  class_methods do
    def last_page_of(size)
      Page.load(ordered, :last, size)
    end

    def page_around(message)
      Page.new(page_before(message) + [ message ] + page_after(message), ordered)
    end

    def paged?
      offset(PAGE_SIZE).exists?
    end
  end
end

require "sqlite3"

# A read-only observer sees commits from every writer, including other runtimes.
# PRAGMA data_version can only be compared on the same persistent connection.
class ResponseCache
  MAX_ENTRY_BYTES = 1.megabyte
  MAX_KEY_BYTES = 2.kilobytes

  def self.instance
    INSTANCE
  end

  def initialize
    @mutex = Mutex.new
    @entries = {}
    @bytes = 0
    @render_locks = Array.new(16) { Mutex.new }
  end

  def budget
    [ ENV.fetch("CAMPFIRE_RESPONSE_CACHE_MB", "64").to_i, 0 ].max.megabytes
  end

  def version
    @mutex.synchronize { current_version }
  rescue SQLite3::Exception
    clear
    nil
  end

  def read(key, version)
    @mutex.synchronize do
      @entries[key]&.first if current_version == version
    end
  rescue SQLite3::Exception
    clear
    nil
  end

  # Collapse cold renders without retaining a mutex for every viewer or URL.
  # Rendering must never hold the observer/entry mutex: controllers read it too.
  def synchronize_render(key, version, &block)
    @render_locks[[ key, version ].hash % @render_locks.length].synchronize(&block)
  end

  def write(key, version, entry)
    size = key.bytesize + entry[:body].bytesize + entry[:headers].sum { |name, value| name.bytesize + value.bytesize } + 256
    return if key.bytesize > MAX_KEY_BYTES || size > [ budget, MAX_ENTRY_BYTES ].min

    @mutex.synchronize do
      return unless current_version == version
      return if @entries.key?(key)

      while @entries.any? && @bytes + size > budget
        _, (_, removed_size) = @entries.shift
        @bytes -= removed_size
      end
      @entries[key] = [ entry, size ]
      @bytes += size
    end
  rescue SQLite3::Exception
    clear
  end

  def clear
    @mutex.synchronize do
      @entries.clear
      @bytes = 0
      @observer&.close
      @observer = @database = @version = nil
    end
  end

  private
    def current_version
      database = File.expand_path(ActiveRecord::Base.connection_db_config.database)
      if @database != database || !@observer
        @entries.clear
        @bytes = 0
        @observer&.close
        @observer = nil
        @observer = SQLite3::Database.new(database, readonly: true)
        @database = database
        @namespace = SecureRandom.hex(16)
        @version = nil
      end

      version = @observer.get_first_value("PRAGMA data_version")
      if @version != version
        @entries.clear
        @bytes = 0
        @version = version
      end
      [ @database, @namespace, @version ]
    end

  INSTANCE = new
end
